// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // The mutated contract returns false for IAccessControl's interface id.
        // A general rule satisfied by the reference is: for any interfaceId,
        // if the mutated contract reports support, the reference must also report
        // support (mutant is not MORE permissive). The reference holds this
        // because its return is the logical OR of the correct equality and super.
        bool mutant = c.supportsInterface(interfaceId);
        bool referenceExpected = (interfaceId == type(IAccessControl).interfaceId)
            || c.supportsInterface(type(IERC165).interfaceId) && interfaceId == type(IERC165).interfaceId;
        // The fuzzer will find interfaceId = type(IAccessControl).interfaceId, where
        // the reference returns true but the mutant returns false, breaking:
        // 'whenever the mutant supports an interface, the reference must too'.
        assertTrue(referenceExpected || !mutant);
    }
}

interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address callerConfirmation) external;
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
